:root {
  --primary: #1e88e5;
  --primary-dark: #1565c0;
  --primary-light: #e3f2fd;
  --accent: #00acc1;
  --text: #1a1a2e;
  --text-light: #546e7a;
  --bg: #f0f4f8;
  --card-bg: #ffffff;
  --success: #43a047;
  --radius: 16px;
  --shadow: 0 8px 32px rgba(30, 136, 229, 0.15);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: linear-gradient(135deg, var(--primary-light) 0%, #b3e5fc 100%);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-dark);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-light);
  margin-bottom: 24px;
}

.goal-display {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 16px;
  font-size: 1rem;
}

.label {
  color: var(--text-light);
}

.value {
  font-weight: 600;
  color: var(--primary-dark);
}

.progress-container {
  background: #e0e0e0;
  border-radius: 999px;
  height: 20px;
  overflow: hidden;
  margin-bottom: 20px;
}

.progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--primary), var(--accent));
  border-radius: 999px;
  transition: width 0.3s ease;
}

.count-display {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
  margin-bottom: 24px;
}

.count {
  font-size: 3rem;
  font-weight: 700;
  color: var(--primary);
  line-height: 1;
}

.count-label {
  font-size: 1.1rem;
  color: var(--text-light);
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 16px;
}

.btn {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: none;
  font-size: 1.75rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.1s, box-shadow 0.2s, background 0.2s;
  color: #fff;
  line-height: 1;
}

.btn-add {
  background: var(--primary);
  box-shadow: 0 4px 12px rgba(30, 136, 229, 0.4);
}

.btn-add:hover {
  background: var(--primary-dark);
  box-shadow: 0 6px 16px rgba(30, 136, 229, 0.5);
}

.btn-add:active {
  transform: scale(0.94);
}

.btn-remove {
  background: var(--accent);
  box-shadow: 0 4px 12px rgba(0, 172, 193, 0.4);
}

.btn-remove:hover:not(:disabled) {
  background: #00838f;
  box-shadow: 0 6px 16px rgba(0, 172, 193, 0.5);
}

.btn-remove:active:not(:disabled) {
  transform: scale(0.94);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

.btn:focus-visible {
  outline: 3px solid var(--primary-dark);
  outline-offset: 3px;
}

.message {
  min-height: 1.5em;
  font-size: 1rem;
  font-weight: 600;
  color: var(--success);
  margin-bottom: 12px;
  transition: opacity 0.3s;
}

.btn-reset {
  background: none;
  border: 1.5px solid var(--text-light);
  color: var(--text-light);
  padding: 8px 20px;
  border-radius: 999px;
  font-size: 0.9rem;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}

.btn-reset:hover {
  background: var(--text-light);
  color: #fff;
}

.btn-reset:active {
  transform: scale(0.96);
}

.btn-reset:focus-visible {
  outline: 3px solid var(--primary-dark);
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .count {
    font-size: 2.5rem;
  }
  .btn {
    width: 56px;
    height: 56px;
    font-size: 1.5rem;
  }
}

const DEFAULT_GOAL = 8;

const goalDisplay = document.getElementById('goalDisplay');
const progressBar = document.getElementById('progressBar');
const progressContainer = document.querySelector('.progress-container');
const glassCount = document.getElementById('glassCount');
const addBtn = document.getElementById('addBtn');
const removeBtn = document.getElementById('removeBtn');
const resetBtn = document.getElementById('resetBtn');
const messageEl = document.getElementById('message');

let goal = DEFAULT_GOAL;
let count = 0;

function updateUI() {
  glassCount.textContent = count;
  const percent = Math.min((count / goal) * 100, 100);
  progressBar.style.width = percent + '%';
  progressContainer.setAttribute('aria-valuenow', count);
  progressContainer.setAttribute('aria-valuemax', goal);

  removeBtn.disabled = count <= 0;
  addBtn.disabled = count >= goal;

  if (count >= goal) {
    messageEl.textContent = '🎉 Goal reached! Great job staying hydrated!';
  } else if (count > 0) {
    messageEl.textContent = `${goal - count} more glass${goal - count === 1 ? '' : 'es'} to go.`;
  } else {
    messageEl.textContent = '';
  }
}

function addGlass() {
  if (count < goal) {
    count++;
    updateUI();
  }
}

function removeGlass() {
  if (count > 0) {
    count--;
    updateUI();
  }
}

function resetTracker() {
  count = 0;
  updateUI();
}

addBtn.addEventListener('click', addGlass);
removeBtn.addEventListener('click', removeGlass);
resetBtn.addEventListener('click', resetTracker);

goalDisplay.textContent = goal + ' glasses';
updateUI();
